T = {
'card82_text': ("A list of company logins is circulating on a hacker forum.", "Una lista de credenciales de la empresa circula por un foro de atacantes."),
'card82_title': ("Logins for Sale", "Credenciales a la venta"),
'card83_opt0_res0': ("30% of employees clicked… The training that follows brings that down to 5%.\n\nDid you know? Internal phishing tests are always done with management's approval and without humiliating anyone.", "El 30 % de los empleados ha hecho clic… La formación posterior baja la cifra al 5 %.\n\n¿Lo sabías? Las pruebas internas de phishing siempre se hacen con el acuerdo de la dirección y sin humillar a nadie."),
'card83_opt0': ("Do it with management's approval", "Hacerlo con el acuerdo de la dirección"),
'card83_opt1_res0': ("Management is furious: they clicked too, and nobody warned them.\n\nDid you know? Without written approval, even a well-meant test causes trouble.", "La dirección está furiosa: también ha hecho clic y nadie le había avisado.\n\n¿Lo sabías? Sin acuerdo por escrito, incluso una prueba bienintencionada da problemas."),
'card83_opt1': ("Do it in secret", "Hacerlo a escondidas"),
'card83_text': ("{0.SimFirstName} wants to send a fake phishing email to all employees to train them.", "{0.SimFirstName} quiere enviar un falso correo de phishing a todos los empleados para entrenarlos."),
'card83_title': ("Fake Phishing Campaign", "Campaña de falso phishing"),
'card84_opt0_res0': ("Even with a stolen password, nobody can get in anymore.\n\nDid you know? Many ransomware attacks start with stolen VPN access.", "Incluso con una contraseña robada, ya nadie puede entrar.\n\n¿Lo sabías? Muchos ataques de ransomware empiezan con un acceso VPN robado."),
'card84_opt0': ("Add two-factor authentication", "Añadir la doble autenticación"),
'card84_opt1_res0': ("A VPN account is used from abroad in the middle of the night…\n\nDid you know? Remote access is one of hackers' favorite entry points.", "Una cuenta VPN se usa desde el extranjero en plena noche…\n\n¿Lo sabías? El acceso remoto es una de las puertas de entrada favoritas de los atacantes."),
'card84_opt1': ("Leave it as is", "Dejarlo así"),
'card84_text': ("The company VPN only asks for a password.", "La VPN de la empresa solo pide una contraseña."),
'card84_title': ("The VPN Without Two-Factor", "La VPN sin doble autenticación"),
'card85_opt0_res0': ("Well done: 3 other employees got the same call and hung up.\n\nDid you know? Microsoft never calls customers to fix their PC: it's a classic scam.", "Bien hecho: otros 3 empleados han recibido la misma llamada y han colgado.\n\n¿Lo sabías? Microsoft nunca llama a sus clientes para reparar su equipo: es una estafa clásica."),
'card85_opt0': ("Tell her to hang up and warn everyone", "Decirle que cuelgue y avisar a todos"),
'card85_opt1_res0': ("She installed the software: the hacker controls her PC.\n\nDid you know? Remote control software is widely used in these scams.", "Ha instalado el programa: el atacante controla su equipo.\n\n¿Lo sabías? Los programas de control remoto se usan mucho en estas estafas."),
'card85_opt1': ("Let her handle it alone", "Dejar que se apañe sola"),
'card85_text': ("An employee gets a call: \"Hello, this is Microsoft support, your PC is infected, install this software.\"", "Una empleada recibe una llamada: «Hola, soporte de Microsoft, su equipo está infectado, instale este programa.»"),
'card85_title': ("The Fake Microsoft Support", "El falso soporte de Microsoft"),
'card86_opt0_res0': ("The department switches to the official tool and keeps the same convenience.\n\nDid you know? \"Shadow IT\" is when employees use tools that IT hasn't approved.", "El departamento pasa a la herramienta oficial y mantiene la misma comodidad.\n\n¿Lo sabías? El «shadow IT» es cuando los empleados usan herramientas no autorizadas por informática."),
'card86_opt0': ("Offer a company-approved solution", "Proponer una solución aprobada por la empresa"),
'card86_opt1_res0': ("The department can't work anymore and complains to management.\n\nDid you know? Offer an alternative before banning something.", "El departamento ya no puede trabajar y se queja a la dirección.\n\n¿Lo sabías? Se propone una alternativa antes de prohibir."),
'card86_opt1': ("Block Dropbox without warning", "Bloquear Dropbox sin avisar"),
'card86_text': ("A department stores company documents in personal Dropbox accounts.", "Un departamento guarda documentos de la empresa en cuentas personales de Dropbox."),
'card86_title': ("Personal Dropbox", "Dropbox personal"),
'card87_opt0_res0': ("His work email is in a separate, protected space on his phone.\n\nDid you know? BYOD (\"bring your own device\") requires keeping work and personal separate.", "Su correo de trabajo está en un espacio separado y protegido de su móvil.\n\n¿Lo sabías? El BYOD («trae tu propio dispositivo») exige separar lo profesional de lo personal."),
'card87_opt0': ("Set up device management", "Implantar una gestión de dispositivos"),
'card87_opt1_res0': ("He loses his phone, which has no PIN… with all the client emails on it.\n\nDid you know? A lost device must be remotely wipeable.", "Pierde su móvil sin código… con todos los correos de clientes dentro.\n\n¿Lo sabías? Un dispositivo perdido debe poder borrarse a distancia."),
'card87_opt1': ("Give him access with no rules", "Darle acceso sin normas"),
'card87_text': ("The sales rep wants to read his work email on his personal phone.", "El comercial quiere leer su correo de trabajo en su móvil personal."),
'card87_title': ("The Personal Phone", "El móvil personal"),
'card88_opt0_res0': ("The work folder is excluded from scanning, the rest stays protected. Everyone's happy.\n\nDid you know? A narrow exclusion is better than a disabled antivirus.", "La carpeta de trabajo queda excluida del análisis y el resto sigue protegido. Todos contentos.\n\n¿Lo sabías? Una exclusión bien acotada es mejor que un antivirus desactivado."),
'card88_opt0': ("Find a compromise (exclude one folder)", "Buscar un término medio (excluir una carpeta)"),
'card88_opt1_res0': ("A booby-trapped library infects his PC, then the network.\n\nDid you know? \"Supply chain\" attacks hide malicious code in components developers use.", "Una librería trampa infecta su equipo y luego la red.\n\n¿Lo sabías? Los ataques a la cadena de suministro esconden código malicioso en componentes que usan los desarrolladores."),
'card88_opt1': ("Let him do it", "Dejarle hacer"),
'card88_text': ("A developer disabled the antivirus on his PC \"because it slows down builds\".", "Un desarrollador ha desactivado el antivirus de su equipo «porque ralentiza las compilaciones»."),
'card88_title': ("The Disabled Antivirus", "El antivirus desactivado"),
'card89_opt0_res0': ("{0.SimFirstName} uncovers a malicious script and stops it before it steals data.\n\nDid you know? An EDR watches how programs behave, not just known viruses.", "{0.SimFirstName} descubre un script malicioso y lo detiene antes de que robe datos.\n\n¿Lo sabías? Un EDR vigila el comportamiento de los programas, no solo los virus conocidos."),
'card89_opt0_res1': ("After analysis, it was a legitimate script from the IT department.\n\nDid you know? Better a false positive than a missed real attack.", "Tras el análisis, era un script legítimo del departamento de informática.\n\n¿Lo sabías? Mejor un falso positivo que un ataque real que se escapa."),
'card89_opt0': ("Investigate right away", "Investigar de inmediato"),
'card89_opt1_res0': ("It was a real attack. Files were stolen.\n\nDid you know? Every alert is checked before it's closed.", "Era un ataque real. Se han robado archivos.\n\n¿Lo sabías? Cada alerta se comprueba antes de archivarla."),
'card89_opt1': ("Mark it as a false positive", "Marcarla como falso positivo"),
'card89_text': ("The EDR flags a strange PowerShell command run on an accountant's PC.", "El EDR señala un comando PowerShell extraño lanzado en el equipo de una contable."),
'card89_title': ("Suspicious PowerShell Command", "Comando PowerShell sospechoso"),
'card90_opt0_res0': ("The honeypot catches a hacker who was already wandering the network!\n\nDid you know? A honeypot is a decoy: nobody should connect to it, so any connection is suspicious.", "¡El honeypot atrapa a un atacante que ya se paseaba por la red!\n\n¿Lo sabías? Un honeypot es un señuelo: nadie debería conectarse a él, así que cualquier conexión es sospechosa."),
'card90_opt0_res1': ("Nothing happens for now. Patience.\n\nDid you know? A honeypot must be well isolated so it doesn't become an entry point.", "De momento no pasa nada. Paciencia.\n\n¿Lo sabías? Un honeypot debe estar bien aislado para no servir de puerta de entrada."),
'card90_opt0': ("Install it in an isolated network", "Instalarlo en una red aislada"),
'card90_opt1_res0': ("The idea is forgotten.\n\nDid you know? Many SOCs use decoys to spot attackers.", "La idea queda olvidada.\n\n¿Lo sabías? Muchos SOC usan señuelos para detectar a los atacantes."),
'card90_opt1': ("Drop the idea", "Abandonar la idea"),
'card90_text': ("{0.SimFirstName} suggests installing a fake server to lure hackers: a \"honeypot\".", "{0.SimFirstName} propone instalar un servidor falso para atraer a los atacantes: un «honeypot»."),
'card90_title': ("The Honeypot", "El tarro de miel"),
'card91_opt0_res0': ("Roles, contacts, steps: the plan is ready and tested during an exercise.\n\nDid you know? The classic steps: detect, contain, eradicate, recover, then learn the lessons.", "Funciones, contactos, etapas: el plan está listo y probado en un simulacro.\n\n¿Lo sabías? Las etapas clásicas: detectar, contener, erradicar, restaurar y sacar conclusiones."),
'card91_opt0_res1': ("The plan exists, but it's too complicated to follow.\n\nDid you know? A good plan fits in a few clear pages.", "El plan existe, pero es demasiado complicado de seguir.\n\n¿Lo sabías? Un buen plan cabe en pocas páginas claras."),
'card91_opt0': ("Write an incident response plan", "Redactar un plan de respuesta a incidentes"),
'card91_opt1_res0': ("Management isn't reassured at all.\n\nDid you know? In the middle of a crisis, there's no time to think: you need a plan ready in advance.", "La dirección no se queda nada tranquila.\n\n¿Lo sabías? En plena crisis no hay tiempo para pensar: hace falta un plan preparado de antemano."),
'card91_opt1': ("Answer \"we'll improvise\"", "Responder «improvisaremos»"),
'card91_text': ("Management asks: \"If we get hacked tomorrow, what do we do?\"", "La dirección pregunta: «Si nos hackean mañana, ¿qué hacemos?»"),
'card91_title': ("The Response Plan", "El plan de respuesta"),
'card92_opt0_res0': ("{0.SimFirstName}'s team wins the CTF! §500 bonus.\n\nDid you know? CTFs (like on Root-Me) are perfect for practicing legally.", "¡El equipo de {0.SimFirstName} gana el CTF! Prima de 500 §.\n\n¿Lo sabías? Los CTF (como en Root-Me) son perfectos para entrenarse legalmente."),
'card92_opt0_res1': ("No win, but a lot learned.\n\nDid you know? Even losing a CTF helps you improve.", "No hay victoria, pero se aprende mucho.\n\n¿Lo sabías? Incluso perder un CTF te hace progresar."),
'card92_opt0': ("Go all in", "Participar a tope"),
'card92_opt1_res0': ("Someone has to watch the alerts!\n\nDid you know? The SOC keeps running even during events.", "¡Alguien tiene que vigilar las alertas!\n\n¿Lo sabías? El SOC sigue funcionando incluso durante los eventos."),
'card92_opt1': ("Stay at your post", "Quedarse en su puesto"),
'card92_text': ("The company is holding a CTF (an ethical hacking competition) between teams.", "La empresa organiza un CTF (una competición de hacking ético) entre equipos."),
'card92_title': ("The Company CTF", "El CTF de la empresa"),
'card93_opt0_res0': ("The \"delivery person\" was a real one… but the rule is reminded to everyone.\n\nDid you know? \"Tailgating\" means getting in by following someone with a badge.", "El «repartidor» era un repartidor de verdad… pero se recuerda la norma a todos.\n\n¿Lo sabías? El «tailgating» consiste en entrar siguiendo a alguien que tiene tarjeta."),
'card93_opt0': ("Check the cameras and the logbook", "Revisar las cámaras y el registro"),
'card93_opt1_res0': ("The same \"delivery person\" comes back and steals a laptop.\n\nDid you know? Physical security is part of cybersecurity.", "El mismo «repartidor» vuelve y roba un portátil.\n\n¿Lo sabías? La seguridad física forma parte de la ciberseguridad."),
'card93_opt1': ("Say nothing", "No decir nada"),
'card93_text': ("A colleague lent their badge to a \"delivery person\" who wanted to get in.", "Un compañero ha prestado su tarjeta a un «repartidor» que quería entrar."),
'card93_title': ("The Borrowed Badge", "La tarjeta prestada"),
'card94_opt0_res0': ("The VPN starts automatically: his data is protected.\n\nDid you know? A hacker can create a fake Wi-Fi with the same name (\"evil twin\") to spy on connections.", "La VPN se activa sola: sus datos están protegidos.\n\n¿Lo sabías? Un atacante puede crear un Wi-Fi falso con el mismo nombre («evil twin») para espiar las conexiones."),
'card94_opt0': ("Make the VPN mandatory outside the office", "Hacer obligatoria la VPN fuera de la oficina"),
'card94_opt1_res0': ("His credentials are intercepted on a fake Wi-Fi…\n\nDid you know? On public Wi-Fi, always use a VPN.", "Sus credenciales se interceptan en un Wi-Fi falso…\n\n¿Lo sabías? En un Wi-Fi público, siempre se usa una VPN."),
'card94_opt1': ("Let it be", "Dejarlo estar"),
'card94_text': ("An employee often works from a café's free Wi-Fi, without a VPN.", "Un empleado trabaja a menudo desde el Wi-Fi gratuito de una cafetería, sin VPN."),
'card94_title': ("The Café's Free Wi-Fi", "El Wi-Fi gratis de la cafetería"),
'card95_opt0_res0': ("Hidden cryptocurrency mining software! {0.SimFirstName} removes it and finds the flaw.\n\nDid you know? \"Cryptojacking\" uses other people's machines to mine cryptocurrency.", "¡Un programa oculto de minería de criptomonedas! {0.SimFirstName} lo elimina y encuentra el fallo.\n\n¿Lo sabías? El «cryptojacking» usa las máquinas de otros para fabricar criptomonedas."),
'card95_opt0_res1': ("{0.SimFirstName} removes the software, but can't find how it got in.\n\nDid you know? If you don't find the cause, the attack will come back.", "{0.SimFirstName} elimina el programa, pero no encuentra cómo entró.\n\n¿Lo sabías? Si no se encuentra la causa, el ataque volverá."),
'card95_opt0': ("Analyze the processes", "Analizar los procesos"),
'card95_opt1_res0': ("Mining resumes right after the reboot.\n\nDid you know? Malware often restarts by itself (persistence).", "La minería vuelve en cuanto se reinicia.\n\n¿Lo sabías? Un programa malicioso suele volver a arrancar solo (persistencia)."),
'card95_opt1': ("Reboot the server", "Reiniciar el servidor"),
'card95_text': ("A server runs at 100% CPU at night, even though nobody is using it.", "Un servidor funciona al 100 % de procesador por la noche, aunque nadie lo usa."),
'card95_title': ("The Server Running Hot", "El servidor que se calienta"),
'card96_opt0_res0': ("With a real attack as an example, management understands and approves the budget.\n\nDid you know? To convince, talk about risks to the business (money, reputation), not technology.", "Con un ejemplo de ataque real, la dirección lo entiende y desbloquea el presupuesto.\n\n¿Lo sabías? Para convencer, se habla de riesgos para la empresa (dinero, imagen), no de técnica."),
'card96_opt0_res1': ("Management sticks to its decision. {0.SimFirstName} has them sign a risk acceptance.\n\nDid you know? When management accepts a risk, it's recorded in writing.", "La dirección mantiene su decisión. {0.SimFirstName} le hace firmar una aceptación del riesgo.\n\n¿Lo sabías? Cuando la dirección acepta un riesgo, queda por escrito."),
'card96_opt0': ("Explain the risk with a concrete example", "Explicar el riesgo con un ejemplo concreto"),
'card96_opt1_res0': ("The flaw is exploited three months later…\n\nDid you know? A pentest report is useless if nothing gets fixed.", "El fallo se explota tres meses después…\n\n¿Lo sabías? Un informe de pentest no sirve de nada si no se corrige."),
'card96_opt1': ("Let it go", "Dejarlo correr"),
'card96_text': ("The pentest found a critical flaw, but management wants to postpone the fix \"until next year\".", "El pentest ha encontrado un fallo crítico, pero la dirección quiere aplazar la corrección «al año que viene»."),
'card96_title': ("The Ignored Report", "El informe ignorado"),
'card97_opt0_res0': ("The disk was encrypted with BitLocker: the thief can't read anything.\n\nDid you know? Disk encryption protects data if the computer is lost or stolen.", "El disco estaba cifrado con BitLocker: el ladrón no puede leer nada.\n\n¿Lo sabías? El cifrado del disco protege los datos si el ordenador se pierde o lo roban."),
'card97_opt0': ("Check that it was encrypted", "Comprobar que estaba cifrado"),
'card97_opt1_res0': ("It wasn't encrypted, and it held client contracts…\n\nDid you know? A personal data breach must be reported to the data protection authority.", "No estaba cifrado, y contenía los contratos de los clientes…\n\n¿Lo sabías? Una fuga de datos personales debe notificarse a la autoridad de protección de datos (en España, la AEPD)."),
'card97_opt1': ("Hope there was nothing important", "Esperar que no hubiera nada importante"),
'card97_text': ("A director's laptop was stolen on the train.", "Han robado el portátil de un director en el tren."),
'card97_title': ("The Stolen Computer", "El ordenador robado"),
'card98_opt0_res0': ("Employees love it! They report twice as many suspicious emails.\n\nDid you know? Well-trained users are the first line of defense.", "¡A los empleados les encanta! Avisan del doble de correos sospechosos.\n\n¿Lo sabías? Los usuarios bien formados son la primera línea de defensa."),
'card98_opt0_res1': ("Nice, but a bit long.\n\nDid you know? Short, regular training works better than one long session a year.", "Simpática, pero un poco larga.\n\n¿Lo sabías? Las formaciones cortas y frecuentes funcionan mejor que una larga al año."),
'card98_opt0': ("Run an interactive quiz with real examples", "Hacer un cuestionario interactivo con ejemplos reales"),
'card98_opt1_res0': ("Half the room falls asleep.\n\nDid you know? Nobody remembers a boring training session.", "La mitad de la sala se duerme.\n\n¿Lo sabías? Nadie retiene una formación aburrida."),
'card98_opt1': ("Read through 80 slides", "Leer 80 diapositivas"),
'card98_text': ("{0.SimFirstName} has to lead a security awareness training session.", "{0.SimFirstName} tiene que impartir una formación de concienciación en seguridad."),
'card98_title': ("Employee Training", "La formación de los empleados"),
'card99_opt0_res0': ("Only the necessary traffic gets through now. The network is much safer.\n\nDid you know? A well-configured firewall blocks everything by default and only allows what's needed.", "Ahora solo pasan los flujos necesarios. La red es mucho más segura.\n\n¿Lo sabías? Un cortafuegos bien configurado lo bloquea todo por defecto y solo permite lo necesario."),
'card99_opt0_res1': ("A business application stops working: a rule was missing.\n\nDid you know? List the required traffic flows before tightening the rules.", "Una aplicación de negocio deja de funcionar: faltaba una regla.\n\n¿Lo sabías? Se listan los flujos necesarios antes de endurecer las reglas."),
'card99_opt0': ("Replace it with precise rules", "Sustituirla por reglas precisas"),
'card99_opt1_res0': ("The firewall is useless as long as this rule exists.\n\nDid you know? Overly broad rules are one of the most common mistakes.", "El cortafuegos no sirve de nada mientras exista esta regla.\n\n¿Lo sabías? Las reglas demasiado amplias son uno de los errores más frecuentes."),
'card99_opt1': ("Leave it alone", "No tocarla"),
}
